--{{{ 回调API

---@param data PurchaseSuccessData
function UnifySDK_Purchase:OnPurchaseSuccess(data)
    if PlayerPrefs.GetInt("4WDClienType",-1)==1 then
        return
    end
    CommonHelper:PlayScreenEffectWaiting(false)
    print("OnPurchaseSuccess" ..tostring(data.cpOrderId) .. "  orderNo" ..tostring(data.orderId) .. " goodsId" ..tostring( data.extraParam))
    local cpOrderId = CommonHelper:IsNullOrEmpty(data.cpOrderId)  and  UnifySDKHelper.currCpOrderID or data.cpOrderId
    cpOrderId = CommonHelper:IsNullOrEmpty(cpOrderId) and tostring(CS.System.DateTime.Now.Ticks) or cpOrderId
    print("OnPurchaseSuccess" ..tostring(cpOrderId))
    SDKHelper:Get():AddPurchase(cpOrderId,data.orderId)
    SDKHelper:Get():SendPurchaseLog("OnPurchaseSuccess" ,"充值成功触发","","","")
end

